/* -----------------------------------------------------------------------
 * B8 -- bytecode independence from parse runtime
 *
 * After frost_parse() returns, the scratch runtime is destroyed.
 * The blob must still work loaded into a fresh runtime.
 * ----------------------------------------------------------------------- */
static void test_B8(void)
{
    group("B8: bytecode independence from parse runtime");

    frost_bytecode *bc = NULL;
    {
        frost_error err = {NULL, 0, 0};
        int rc = frost_parse("var independence = 1;", "indep.js", &bc, &err);
        CHECK_EQ(rc, 0);
        CHECK_NOTNULL(bc);
        frost_error_free(&err);
        /* Scratch runtime is already gone inside frost_parse */
    }

    /* bc is valid even though the parse runtime is long destroyed */
    size_t sz = frost_bytecode_size(bc);
    CHECK(sz > 0);

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_load(rt, bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    rc = frost_runtime_eval_loaded(rt, bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc);
}

