/* -----------------------------------------------------------------------
 * B10 -- frost_runtime_eval_loaded multiple times on same runtime
 * ----------------------------------------------------------------------- */
static void test_B10(void)
{
    group("B10: eval_loaded multiple times on same runtime");

    /* Use a simple source with no persistent side effects between evals */
    frost_bytecode *bc = NULL;
    frost_parse("(function(){var x=1;return x+1;})();", "multi.js", &bc, NULL);
    CHECK_NOTNULL(bc);

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_load(rt, bc, &err);
    CHECK_EQ(rc, 0);

    /* Eval 3 times -- should succeed each time */
    for (int i = 0; i < 3; i++) {
        err = NULL;
        rc = frost_runtime_eval_loaded(rt, bc, &err);
        CHECK_EQ(rc, 0);
        CHECK_NULL(err);
    }

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc);
}

/* -----------------------------------------------------------------------
 * B11 -- frost_runtime_load replaces previously loaded bytecode
 * ----------------------------------------------------------------------- */
static void test_B11(void)
{
    group("B11: load replaces previous load");

    frost_bytecode *bc1 = NULL;
    frost_bytecode *bc2 = NULL;
    frost_parse("var first = 1;", "first.js", &bc1, NULL);
    frost_parse("var second = 2;", "second.js", &bc2, NULL);
    CHECK_NOTNULL(bc1);
    CHECK_NOTNULL(bc2);

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_load(rt, bc1, &err);
    CHECK_EQ(rc, 0);

    /* Load again with different bytecode -- should free old and accept new */
    rc = frost_runtime_load(rt, bc2, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    /* Eval should run the second bytecode */
    rc = frost_runtime_eval_loaded(rt, bc2, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc1);
    frost_bytecode_destroy(bc2);
}

