/* -----------------------------------------------------------------------
 * B13 -- frost_runtime_load NULL / bad args
 * ----------------------------------------------------------------------- */
static void test_B13(void)
{
    group("B13: frost_runtime_load NULL/bad-arg safety");

    /* Both NULL */
    char *err = NULL;
    int rc = frost_runtime_load(NULL, NULL, &err);
    CHECK_EQ(rc, -1);
    free(err);

    /* NULL err -- should not crash */
    rc = frost_runtime_load(NULL, NULL, NULL);
    CHECK_EQ(rc, -1);

    /* frost_runtime_eval_loaded NULL runtime */
    err = NULL;
    rc = frost_runtime_eval_loaded(NULL, NULL, &err);
    CHECK_EQ(rc, -1);
    free(err);
}

